function CountryFlag({country,className='config-country-flag'}){const name=typeof country==='string'?country:country?.name||'';const logo=typeof country==='object'?String(country?.logo||''):'';const fallback=getCountryFlagCode(name);const emoji=/^\p{Extended_Pictographic}/u.test(logo)?logo:'';const makeFallback=()=>fallback?'https://flagcdn.com/w40/'+fallback+'.png':'';const [src,setSrc]=useState(emoji?'':(logo||makeFallback()));const [failed,setFailed]=useState(false);useEffect(()=>{setSrc(emoji?'':(logo||makeFallback()));setFailed(false)},[logo,fallback,emoji]);if(emoji)return <span className={className+' flag-emoji'} title={name} aria-label={name}>{emoji}</span>;if(!src||failed)return <span className={className+' flag-fallback'} aria-label={name} title={name}><Icon name='flag'/></span>;return <img className={className} src={src} alt={name?'Bandeira de '+name:''} title={name} loading='lazy' referrerPolicy='no-referrer' onError={()=>{if(fallback&&!src.includes('flagcdn.com'))setSrc(makeFallback());else setFailed(true)}}/>}
